/**
 * Dedicated IP Provisioning Module
 *
 * Creates and destroys per-tenant NAT Gateway + EIP + Subnet + Lambda
 * within the shared VPC for tenants requiring a unique outbound IP.
 *
 * Architecture: Single-VPC-Multi-NAT approach (shared VPC, per-tenant subnets)
 *
 * Provisioning creates:
 *   1. Elastic IP
 *   2. Public subnet (for NAT Gateway)
 *   3. Private subnet (for Lambda)
 *   4. Internet Gateway route in public subnet
 *   5. NAT Gateway in public subnet with EIP
 *   6. Route table for private subnet → NAT Gateway
 *   7. Security Group (outbound LDAP/LDAPS)
 *   8. IAM Role for per-tenant Lambda
 *   9. Lambda Function (code from S3, VPC-attached to private subnet)
 *
 * Cleanup reverses all of the above.
 */

import {
  EC2Client,
  AllocateAddressCommand,
  DescribeAddressesCommand,
  ReleaseAddressCommand,
  CreateSubnetCommand,
  DeleteSubnetCommand,
  CreateNatGatewayCommand,
  DeleteNatGatewayCommand,
  DescribeNatGatewaysCommand,
  CreateRouteTableCommand,
  DeleteRouteTableCommand,
  CreateRouteCommand,
  AssociateRouteTableCommand,
  DisassociateRouteTableCommand,
  CreateSecurityGroupCommand,
  DeleteSecurityGroupCommand,
  DescribeNetworkInterfacesCommand,
  DeleteNetworkInterfaceCommand,
  AuthorizeSecurityGroupEgressCommand,
  RevokeSecurityGroupEgressCommand,
  DescribeSubnetsCommand,
  DescribeRouteTablesCommand,
  DescribeSecurityGroupsCommand,
} from '@aws-sdk/client-ec2';
import {
  LambdaClient,
  CreateFunctionCommand,
  DeleteFunctionCommand,
  GetFunctionCommand,
  waitUntilFunctionActiveV2,
} from '@aws-sdk/client-lambda';
import {
  IAMClient,
  CreateRoleCommand,
  DeleteRoleCommand,
  AttachRolePolicyCommand,
  DetachRolePolicyCommand,
  PutRolePolicyCommand,
  DeleteRolePolicyCommand,
  GetRoleCommand,
} from '@aws-sdk/client-iam';
import { DynamoDBClient, GetItemCommand, UpdateItemCommand, QueryCommand as DDBQueryCommand } from '@aws-sdk/client-dynamodb';
import { CloudWatchClient, PutMetricAlarmCommand, DeleteAlarmsCommand } from '@aws-sdk/client-cloudwatch';
import { UpdateFunctionCodeCommand } from '@aws-sdk/client-lambda';
import {
  DEDICATED_IP_CONFIG_TYPE,
  deserializeStateItem,
} from './dedicated-ip-state.mjs';
import {
  assertCidrOwnership,
  canReleaseCidr,
  compactResourceJournal,
  createOptionalResourceWithRequiredCheckpoint,
  dedicatedSubnetCidrs,
  eipAllocationRequest,
  operationTags,
  selectCidrIndex,
  selectAvailabilityZoneName,
} from './dedicated-ip-resources.mjs';
import { updateAsmAppSrvIP } from './asm-app-srv-ip.mjs';

const ec2 = new EC2Client({});
const lambdaClient = new LambdaClient({});
const iam = new IAMClient({});
const dynamodb = new DynamoDBClient({});

const ACCOUNT_ID = process.env.ACCOUNT_ID || '';
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';
const CONFIG_TABLE = process.env.CONFIG_TABLE || 'amfa-configtable';
const TENANT_TABLE = process.env.AMFATENANT_TABLE || 'amfa-tenanttable';
const VPC_ID = process.env.VPC_ID || '';
const IGW_ID = process.env.IGW_ID || ''; // Internet Gateway of shared VPC
const WORKER_CODE_S3_BUCKET = process.env.WORKER_CODE_S3_BUCKET || `${ACCOUNT_ID}-${AWS_REGION}-ad-sync-state`;
const WORKER_CODE_S3_KEY = process.env.WORKER_CODE_S3_KEY || 'worker-code/latest.zip';
const WORKER_CODE_VERSION = process.env.WORKER_CODE_VERSION || 'latest';
const SYNC_STATE_BUCKET = process.env.SYNC_STATE_BUCKET || `${ACCOUNT_ID}-${AWS_REGION}-ad-sync-state`;
const NAT_EIP_ADDRESS = process.env.NAT_EIP_ADDRESS || ''; // shared NAT IP (fallback)
// Runtime version for per-tenant Lambdas — should match the shared worker runtime.
// Read from env (set by CDK/installer) or default to nodejs22.x.
const WORKER_LAMBDA_RUNTIME = process.env.WORKER_LAMBDA_RUNTIME || 'nodejs22.x';

const VPC_CIDR = process.env.VPC_CIDR || '10.0.0.0/16';
const CIDR_START_INDEX = 10; // Indices 0-9 reserved for shared infra
const CIDR_MAX_INDEX = 255; // Maximum third-octet value in a /16 VPC

/**
 * Enable dedicated IP for a tenant.
 *
 * Creates all required AWS resources and updates the tenant's adSyncConfig.
 *
 * @param {string} tenantId
 * @returns {Promise<Object>} { dedicatedEipAddress, dedicatedLambdaArn, ... }
 */
export async function enableDedicatedIp(tenantId, operationId, {
  stateStore,
  context,
} = {}) {
  console.log(JSON.stringify({
    level: "INFO",
    event: "DEDICATED_IP_ENABLE_START",
    tenantId,
    operationId,
  }));

  if (!VPC_ID) {
    throw new Error('VPC_ID not configured. Shared VPC must be deployed first.');
  }
  if (!IGW_ID) {
    throw new Error('IGW_ID not configured. Internet Gateway must exist in shared VPC.');
  }

  // Track created resources for rollback
  const resources = {};
  const checkpoint = async (name, value) => {
    resources[name] = value;
    await stateStore.checkpointResource(
      tenantId,
      'provisioning',
      operationId,
      name,
      value,
    );
  };
  const ensureTimeRemaining = (minimumMs = 60_000) => {
    if (context?.getRemainingTimeInMillis?.() < minimumMs) {
      throw new Error('Provisioning stopped before the Lambda timeout.');
    }
  };

  try {
    // Step 1: Allocate CIDR index
    const cidrIndex = await allocateCidrIndex(tenantId);
    await checkpoint('cidrIndex', cidrIndex);
    const { privateCidr, publicCidr } = dedicatedSubnetCidrs(
      VPC_CIDR,
      cidrIndex,
    );
    const availabilityZone = await selectAvailabilityZone();

    console.log(JSON.stringify({ level: "INFO", event: "CIDR_ALLOCATED", tenantId, cidrIndex, privateCidr, publicCidr }));

    // Step 2: Allocate Elastic IP
    const eipResult = await ec2.send(new AllocateAddressCommand(
      eipAllocationRequest(tenantId, operationId),
    ));
    await checkpoint('eipAllocationId', eipResult.AllocationId);
    await checkpoint('eipAddress', eipResult.PublicIp);
    console.log(JSON.stringify({ level: "INFO", event: "EIP_ALLOCATED", tenantId, eip: eipResult.PublicIp }));

    // Step 3: Create public subnet (for NAT Gateway)
    ensureTimeRemaining();
    const publicSubnet = await ec2.send(new CreateSubnetCommand({
      VpcId: VPC_ID,
      CidrBlock: publicCidr,
      AvailabilityZone: availabilityZone,
      TagSpecifications: [{
        ResourceType: 'subnet',
        Tags: [
          ...operationTags(tenantId, operationId, `dedicated-ip-public-${tenantId}`),
          { Key: 'Purpose', Value: 'dedicated-ip-nat' },
        ],
      }],
    }));
    await checkpoint('publicSubnetId', publicSubnet.Subnet.SubnetId);
    console.log(JSON.stringify({ level: "INFO", event: "PUBLIC_SUBNET_CREATED", tenantId, subnetId: resources.publicSubnetId }));

    // Step 4: Create private subnet (for Lambda)
    ensureTimeRemaining();
    const privateSubnet = await ec2.send(new CreateSubnetCommand({
      VpcId: VPC_ID,
      CidrBlock: privateCidr,
      AvailabilityZone: availabilityZone,
      TagSpecifications: [{
        ResourceType: 'subnet',
        Tags: [
          ...operationTags(tenantId, operationId, `dedicated-ip-private-${tenantId}`),
          { Key: 'Purpose', Value: 'dedicated-ip-lambda' },
        ],
      }],
    }));
    await checkpoint('privateSubnetId', privateSubnet.Subnet.SubnetId);
    console.log(JSON.stringify({ level: "INFO", event: "PRIVATE_SUBNET_CREATED", tenantId, subnetId: resources.privateSubnetId }));

    // Step 5: Create route table for public subnet → IGW
    ensureTimeRemaining();
    const publicRt = await ec2.send(new CreateRouteTableCommand({
      VpcId: VPC_ID,
      TagSpecifications: [{
        ResourceType: 'route-table',
        Tags: operationTags(
          tenantId,
          operationId,
          `dedicated-ip-publicrt-${tenantId}`,
        ),
      }],
    }));
    await checkpoint('publicRouteTableId', publicRt.RouteTable.RouteTableId);

    await ec2.send(new CreateRouteCommand({
      RouteTableId: resources.publicRouteTableId,
      DestinationCidrBlock: '0.0.0.0/0',
      GatewayId: IGW_ID,
    }));

    const publicAssoc = await ec2.send(new AssociateRouteTableCommand({
      RouteTableId: resources.publicRouteTableId,
      SubnetId: resources.publicSubnetId,
    }));
    await checkpoint('publicRtAssociationId', publicAssoc.AssociationId);
    console.log(JSON.stringify({ level: "INFO", event: "PUBLIC_ROUTE_TABLE_CREATED", tenantId }));

    // Step 6: Create NAT Gateway in public subnet with EIP
    ensureTimeRemaining(7 * 60_000);
    const natGw = await ec2.send(new CreateNatGatewayCommand({
      SubnetId: resources.publicSubnetId,
      AllocationId: resources.eipAllocationId,
      TagSpecifications: [{
        ResourceType: 'natgateway',
        Tags: operationTags(tenantId, operationId, `dedicated-ip-nat-${tenantId}`),
      }],
    }));
    await checkpoint('natGatewayId', natGw.NatGateway.NatGatewayId);
    console.log(JSON.stringify({ level: "INFO", event: "NAT_GATEWAY_CREATING", tenantId, natGwId: resources.natGatewayId }));

    // Wait for NAT Gateway to become available (can take 1-2 minutes)
    await waitForNatGateway(resources.natGatewayId, 300, context);
    console.log(JSON.stringify({ level: "INFO", event: "NAT_GATEWAY_AVAILABLE", tenantId }));

    // Step 7: Create route table for private subnet → NAT Gateway
    ensureTimeRemaining();
    const privateRt = await ec2.send(new CreateRouteTableCommand({
      VpcId: VPC_ID,
      TagSpecifications: [{
        ResourceType: 'route-table',
        Tags: operationTags(
          tenantId,
          operationId,
          `dedicated-ip-privatert-${tenantId}`,
        ),
      }],
    }));
    await checkpoint('privateRouteTableId', privateRt.RouteTable.RouteTableId);

    await ec2.send(new CreateRouteCommand({
      RouteTableId: resources.privateRouteTableId,
      DestinationCidrBlock: '0.0.0.0/0',
      NatGatewayId: resources.natGatewayId,
    }));

    const privateAssoc = await ec2.send(new AssociateRouteTableCommand({
      RouteTableId: resources.privateRouteTableId,
      SubnetId: resources.privateSubnetId,
    }));
    await checkpoint('privateRtAssociationId', privateAssoc.AssociationId);
    console.log(JSON.stringify({ level: "INFO", event: "PRIVATE_ROUTE_TABLE_CREATED", tenantId }));

    // Step 8: Create Security Group (outbound LDAP/LDAPS only)
    ensureTimeRemaining();
    const sg = await ec2.send(new CreateSecurityGroupCommand({
      GroupName: `dedicated-ip-sg-${tenantId}`,
      Description: `Security group for dedicated IP Lambda - tenant ${tenantId}`,
      VpcId: VPC_ID,
      TagSpecifications: [{
        ResourceType: 'security-group',
        Tags: operationTags(
          tenantId,
          operationId,
          `dedicated-ip-sg-${tenantId}`,
        ),
      }],
    }));
    await checkpoint('securityGroupId', sg.GroupId);

    // Revoke default all-outbound rule, then add specific LDAP/LDAPS/DNS rules
    try {
      await ec2.send(new RevokeSecurityGroupEgressCommand({
        GroupId: resources.securityGroupId,
        IpPermissions: [{ IpProtocol: '-1', IpRanges: [{ CidrIp: '0.0.0.0/0' }] }],
      }));
    } catch (e) { /* ignore if already revoked */ }

    // Allow outbound: LDAP (389), LDAPS (636), DNS (53), HTTPS (443)
    await ec2.send(new AuthorizeSecurityGroupEgressCommand({
      GroupId: resources.securityGroupId,
      IpPermissions: [
        { IpProtocol: 'tcp', FromPort: 389, ToPort: 389, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 636, ToPort: 636, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 53, ToPort: 53, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'udp', FromPort: 53, ToPort: 53, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
        { IpProtocol: 'tcp', FromPort: 443, ToPort: 443, IpRanges: [{ CidrIp: '0.0.0.0/0' }] },
      ],
    }));
    console.log(JSON.stringify({ level: "INFO", event: "SECURITY_GROUP_CREATED", tenantId }));

    // Step 9: Create IAM Role
    ensureTimeRemaining(2 * 60_000);
    const roleName = `ad-sync-dedicated-${tenantId}`;
    const roleArn = await createWorkerRole(roleName, tenantId, operationId);
    await checkpoint('iamRoleName', roleName);
    await checkpoint('iamRoleArn', roleArn);

    // Wait for IAM role propagation (AWS docs: up to 15-20s in some cases)
    ensureTimeRemaining(90_000);
    await new Promise(r => setTimeout(r, 15000));
    console.log(JSON.stringify({ level: "INFO", event: "IAM_ROLE_CREATED", tenantId, roleName }));

    // Step 10: Create Lambda Function
    // NOTE: Per-tenant dedicated Lambda does NOT use the admin-auth layer (it's a standalone
    // worker). The worker code in S3 must be self-contained with all dependencies bundled.
    // If the ad-sync-worker requires tenant-utils layer, it must be bundled into the zip.
    const functionName = `ad-sync-worker-tenant-${tenantId}`;
    ensureTimeRemaining(3 * 60_000);

    await lambdaClient.send(new CreateFunctionCommand({
      FunctionName: functionName,
      Runtime: WORKER_LAMBDA_RUNTIME,
      Handler: 'index.handler',
      Role: roleArn,
      Code: {
        S3Bucket: WORKER_CODE_S3_BUCKET,
        S3Key: WORKER_CODE_S3_KEY,
      },
      VpcConfig: {
        SubnetIds: [resources.privateSubnetId],
        SecurityGroupIds: [resources.securityGroupId],
      },
      Environment: {
        Variables: {
          CONFIG_TABLE: CONFIG_TABLE,
          TENANT_TABLE: TENANT_TABLE,
          SYNC_STATE_BUCKET: SYNC_STATE_BUCKET,
        },
      },
      Timeout: 900, // 15 minutes
      MemorySize: 1024,
      Tags: {
        TenantId: tenantId,
        ManagedBy: 'vpnconfig-lambda',
        OperationId: operationId,
        Purpose: 'dedicated-ip-ad-sync-worker',
      },
    }));
    await checkpoint('lambdaFunctionName', functionName);

    // Reserve one minute for checkpointing and the terminal state write.
    // Cap at 420s: a VPC Lambda in a brand-new subnet/SG pair needs a fresh
    // Hyperplane ENI, which routinely takes 2-4+ minutes to provision.
    const remainingBeforeWaiter =
      context?.getRemainingTimeInMillis?.() ?? 8 * 60_000;
    const lambdaWaitSeconds = Math.min(
      420,
      Math.floor((remainingBeforeWaiter - 60_000) / 1000),
    );
    if (lambdaWaitSeconds < 30) {
      throw new Error('Provisioning stopped before the Lambda activation waiter.');
    }
    // Explicit min/maxDelay: the SDK default exponential backoff grows the
    // interval so fast that it aborts with TIMEOUT after ~10 polls, long
    // before maxWaitTime is reached. Steady 5-15s polling uses the budget.
    await waitUntilFunctionActiveV2(
      { client: lambdaClient, maxWaitTime: lambdaWaitSeconds, minDelay: 5, maxDelay: 15 },
      { FunctionName: functionName },
    );

    const lambdaArn = `arn:aws:lambda:${AWS_REGION}:${ACCOUNT_ID}:function:${functionName}`;
    await checkpoint('lambdaArn', lambdaArn);
    console.log(JSON.stringify({ level: "INFO", event: "LAMBDA_CREATED", tenantId, functionName }));

    // Step 10b: Create CloudWatch error alarm for per-tenant Lambda
    const ALARM_SNS_TOPIC_ARN = process.env.ALARM_SNS_TOPIC_ARN || '';
    if (ALARM_SNS_TOPIC_ARN) {
      const alarmName = `amfa-dedicated-ip-errors-${tenantId}`;
      const alarmCreated = await createOptionalResourceWithRequiredCheckpoint({
        create: async () => {
          const cwClient = new CloudWatchClient({});
          await cwClient.send(new PutMetricAlarmCommand({
            AlarmName: alarmName,
            AlarmDescription: `Dedicated IP Lambda errors for tenant ${tenantId}`,
            Namespace: 'AWS/Lambda',
            MetricName: 'Errors',
            Dimensions: [{ Name: 'FunctionName', Value: functionName }],
            Statistic: 'Sum',
            Period: 300,
            EvaluationPeriods: 1,
            Threshold: 1,
            ComparisonOperator: 'GreaterThanOrEqualToThreshold',
            TreatMissingData: 'notBreaching',
            AlarmActions: [ALARM_SNS_TOPIC_ARN],
            OKActions: [ALARM_SNS_TOPIC_ARN],
          }));
        },
        checkpoint: () => checkpoint('alarmName', alarmName),
        onCreateError: alarmErr => {
          console.error(JSON.stringify({
            level: "ERROR",
            event: "DEDICATED_LAMBDA_ALARM_FAILED",
            tenantId,
            error: alarmErr.message,
          }));
        },
      });
      if (alarmCreated) {
        console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_LAMBDA_ALARM_CREATED", tenantId }));
      }
    }

    // Record worker code version used
    await checkpoint('workerCodeVersion', WORKER_CODE_VERSION);
    await checkpoint('workerCodeS3Key', WORKER_CODE_S3_KEY);

    // Step 11: Update ASM appSrvIP with new dedicated EIP (if ASM integration is active)
    await updateAsmAppSrvIP(tenantId, resources.eipAddress);
    await stateStore.completeProvisioning(tenantId, operationId, {
      dedicatedEipAddress: resources.eipAddress,
      dedicatedLambdaArn: lambdaArn,
      resources,
    });

    console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_IP_ENABLE_COMPLETE", tenantId, eip: resources.eipAddress }));

    return {
      dedicatedEipAddress: resources.eipAddress,
      dedicatedLambdaArn: lambdaArn,
      resources,
    };
  } catch (error) {
    console.error(JSON.stringify({
      level: "ERROR",
      event: "DEDICATED_IP_ENABLE_FAILED",
      tenantId,
      operationId,
      error: error.message,
      resources: Object.keys(resources),
    }));
    throw error;
  }
}

/**
 * Disable dedicated IP for a tenant — cleanup all provisioned resources.
 */
export async function cleanupDedicatedIp(tenantId, operationId, mode, {
  stateStore,
  context,
} = {}) {
  const state = await stateStore.load(tenantId);
  const previousError = state?.error || null;
  let resources = { ...(state?.resources || {}) };
  let result;
  try {
    resources = await discoverOperationResources(
      tenantId,
      state?.resourceOperationId || operationId,
      resources,
    );
    for (const [name, value] of Object.entries(resources)) {
      if (state?.resources?.[name] === undefined) {
        await stateStore.checkpointResource(
          tenantId,
          mode,
          operationId,
          name,
          value,
        );
      }
    }
    await updateAsmAppSrvIP(tenantId, NAT_EIP_ADDRESS);
    result = await rollbackResources(tenantId, resources, { context });
  } catch (error) {
    try {
      await stateStore.failCleanup(
        tenantId,
        mode,
        operationId,
        resources,
        'Cleanup did not complete. Retry cleanup.',
      );
    } catch (stateError) {
      console.error(JSON.stringify({
        level: 'ERROR',
        event: 'CLEANUP_FAILURE_STATE_WRITE_FAILED',
        tenantId,
        operationId,
        cleanupError: error.message,
        stateError: stateError.message,
      }));
      error.statePersistenceError = stateError;
    }
    throw error;
  }
  if (Object.keys(result.remaining).length === 0) {
    await stateStore.recordCleanupProgress(
      tenantId,
      mode,
      operationId,
      result.remaining,
    );
    await stateStore.completeCleanup(
      tenantId,
      mode,
      operationId,
      mode === 'rolling_back' ? previousError : null,
    );
    return result;
  }

  await stateStore.failCleanup(
    tenantId,
    mode,
    operationId,
    result.remaining,
    'Cleanup did not complete. Retry cleanup.',
  );
  return result;
}

async function discoverOperationResources(tenantId, resourceOperationId, existing) {
  if (!resourceOperationId) return existing;
  const resources = { ...existing };
  const filters = [
    { Name: 'tag:TenantId', Values: [tenantId] },
    { Name: 'tag:ManagedBy', Values: ['vpnconfig-lambda'] },
    { Name: 'tag:OperationId', Values: [resourceOperationId] },
  ];
  const tagValue = (tags, key) => tags?.find(tag => tag.Key === key)?.Value;

  const [addresses, subnets, natGateways, routeTables, securityGroups] = await Promise.all([
    ec2.send(new DescribeAddressesCommand({ Filters: filters })),
    ec2.send(new DescribeSubnetsCommand({ Filters: filters })),
    ec2.send(new DescribeNatGatewaysCommand({ Filter: filters })),
    ec2.send(new DescribeRouteTablesCommand({ Filters: filters })),
    ec2.send(new DescribeSecurityGroupsCommand({ Filters: filters })),
  ]);

  const address = addresses.Addresses?.[0];
  if (address) {
    resources.eipAllocationId ||= address.AllocationId;
    resources.eipAddress ||= address.PublicIp;
  }
  for (const subnet of subnets.Subnets || []) {
    const purpose = tagValue(subnet.Tags, 'Purpose');
    if (purpose === 'dedicated-ip-nat') resources.publicSubnetId ||= subnet.SubnetId;
    if (purpose === 'dedicated-ip-lambda') resources.privateSubnetId ||= subnet.SubnetId;
  }
  resources.natGatewayId ||= natGateways.NatGateways?.[0]?.NatGatewayId;
  for (const routeTable of routeTables.RouteTables || []) {
    const name = tagValue(routeTable.Tags, 'Name') || '';
    const associationId = routeTable.Associations?.find(association => !association.Main)
      ?.RouteTableAssociationId;
    if (name.includes('publicrt')) {
      resources.publicRouteTableId ||= routeTable.RouteTableId;
      resources.publicRtAssociationId ||= associationId;
    }
    if (name.includes('privatert')) {
      resources.privateRouteTableId ||= routeTable.RouteTableId;
      resources.privateRtAssociationId ||= associationId;
    }
  }
  resources.securityGroupId ||= securityGroups.SecurityGroups?.[0]?.GroupId;

  const functionName = `ad-sync-worker-tenant-${tenantId}`;
  try {
    const result = await lambdaClient.send(new GetFunctionCommand({
      FunctionName: functionName,
    }));
    if (
      result.Tags?.TenantId === tenantId
      && result.Tags?.ManagedBy === 'vpnconfig-lambda'
      && result.Tags?.OperationId === resourceOperationId
    ) {
      resources.lambdaFunctionName ||= functionName;
      resources.lambdaArn ||= result.Configuration?.FunctionArn;
    }
  } catch (error) {
    if (error.name !== 'ResourceNotFoundException') throw error;
  }

  const roleName = `ad-sync-dedicated-${tenantId}`;
  try {
    const result = await iam.send(new GetRoleCommand({ RoleName: roleName }));
    if (
      tagValue(result.Role?.Tags, 'TenantId') === tenantId
      && tagValue(result.Role?.Tags, 'ManagedBy') === 'vpnconfig-lambda'
      && tagValue(result.Role?.Tags, 'OperationId') === resourceOperationId
    ) {
      resources.iamRoleName ||= roleName;
      resources.iamRoleArn ||= result.Role?.Arn;
    }
  } catch (error) {
    if (error.name !== 'NoSuchEntityException') throw error;
  }

  resources.cidrIndex ??= await findCidrAllocation(tenantId);
  if (process.env.ALARM_SNS_TOPIC_ARN) {
    resources.alarmName ||= `amfa-dedicated-ip-errors-${tenantId}`;
  }
  return Object.fromEntries(
    Object.entries(resources).filter(([, value]) => value !== undefined),
  );
}

/**
 * Update all existing dedicated Lambda functions to use the latest worker code from S3.
 * Called after a new deployment to sync per-tenant Lambdas with the shared worker code.
 *
 * Scans all dedicatedIpState items for mode === 'dedicated',
 * then calls UpdateFunctionCode on each per-tenant Lambda.
 *
 * @returns {Promise<Object>} { updated: number, failed: number, results: [...] }
 */
export async function updateDedicatedWorkers() {

  console.log(JSON.stringify({ level: "INFO", event: "UPDATE_DEDICATED_WORKERS_START", s3Key: WORKER_CODE_S3_KEY, version: WORKER_CODE_VERSION }));

  // Query the dedicated state items via GSI.
  const allItems = [];
  let lastKey = undefined;
  do {
    const result = await dynamodb.send(new DDBQueryCommand({
      TableName: CONFIG_TABLE,
      IndexName: 'configtype-index',
      KeyConditionExpression: 'configtype = :ct',
      ExpressionAttributeValues: { ':ct': { S: DEDICATED_IP_CONFIG_TYPE } },
      ...(lastKey ? { ExclusiveStartKey: lastKey } : {}),
    }));
    allItems.push(...(result.Items || []));
    lastKey = result.LastEvaluatedKey;
  } while (lastKey);

  // Filter to tenants with dedicated mode (skip provisioning/deprovisioning — those are in-flight)
  const dedicatedTenants = allItems
    .map(item => ({ tenantId: item.id.S, state: deserializeStateItem(item) }))
    .filter(t => t.state.mode === 'dedicated' && t.state.dedicatedLambdaArn);

  if (dedicatedTenants.length === 0) {
    console.log(JSON.stringify({ level: "INFO", event: "NO_DEDICATED_WORKERS", message: "No dedicated Lambda functions to update" }));
    return { updated: 0, failed: 0, results: [] };
  }

  console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_WORKERS_FOUND", count: dedicatedTenants.length }));

  const results = [];
  for (const { tenantId, state } of dedicatedTenants) {
    const functionName = state.resources?.lambdaFunctionName
      || state.dedicatedLambdaArn.split(':').pop();
    const currentVersion = state.resources?.workerCodeVersion || 'unknown';

    // Skip if already on latest version
    if (currentVersion === WORKER_CODE_VERSION && WORKER_CODE_VERSION !== 'latest') {
      results.push({ tenantId, functionName, status: 'skipped', reason: `already on ${WORKER_CODE_VERSION}` });
      continue;
    }

    try {
      await lambdaClient.send(new UpdateFunctionCodeCommand({
        FunctionName: functionName,
        S3Bucket: WORKER_CODE_S3_BUCKET,
        S3Key: WORKER_CODE_S3_KEY,
      }));

      await dynamodb.send(new UpdateItemCommand({
        TableName: CONFIG_TABLE,
        Key: {
          id: { S: tenantId },
          configtype: { S: DEDICATED_IP_CONFIG_TYPE },
        },
        UpdateExpression: [
          'SET #resources.#version = :version',
          '#resources.#s3Key = :s3Key',
          '#resources.#lastUpdate = :lastUpdate',
        ].join(', '),
        ConditionExpression: '#mode = :dedicated',
        ExpressionAttributeNames: {
          '#resources': 'resources',
          '#version': 'workerCodeVersion',
          '#s3Key': 'workerCodeS3Key',
          '#lastUpdate': 'lastCodeUpdate',
          '#mode': 'mode',
        },
        ExpressionAttributeValues: {
          ':version': { S: WORKER_CODE_VERSION },
          ':s3Key': { S: WORKER_CODE_S3_KEY },
          ':lastUpdate': { S: new Date().toISOString() },
          ':dedicated': { S: 'dedicated' },
        },
      }));

      results.push({ tenantId, functionName, status: 'updated', fromVersion: currentVersion, toVersion: WORKER_CODE_VERSION });
      console.log(JSON.stringify({ level: "INFO", event: "DEDICATED_WORKER_UPDATED", tenantId, functionName, fromVersion: currentVersion, toVersion: WORKER_CODE_VERSION }));
    } catch (err) {
      results.push({ tenantId, functionName, status: 'failed', error: err.message });
      console.error(JSON.stringify({ level: "ERROR", event: "DEDICATED_WORKER_UPDATE_FAILED", tenantId, functionName, error: err.message }));
    }
  }

  const updated = results.filter(r => r.status === 'updated').length;
  const skipped = results.filter(r => r.status === 'skipped').length;
  const failed = results.filter(r => r.status === 'failed').length;

  console.log(JSON.stringify({ level: "INFO", event: "UPDATE_DEDICATED_WORKERS_COMPLETE", updated, skipped, failed, version: WORKER_CODE_VERSION }));
  return { updated, skipped, failed, version: WORKER_CODE_VERSION, results };
}

