async function waitForNatGateway(natGatewayId, maxWaitSec = 300, context) {
  const startTime = Date.now();
  while (Date.now() - startTime < maxWaitSec * 1000) {
    if (context?.getRemainingTimeInMillis?.() < 60_000) {
      throw new Error('NAT Gateway wait stopped before the Lambda timeout.');
    }
    const desc = await ec2.send(new DescribeNatGatewaysCommand({
      NatGatewayIds: [natGatewayId],
    }));
    const state = desc.NatGateways?.[0]?.State;
    if (state === 'available') return;
    if (state === 'failed') throw new Error(`NAT Gateway ${natGatewayId} failed to create`);
    await new Promise(r => setTimeout(r, 5000));
  }
  throw new Error(`NAT Gateway ${natGatewayId} did not become available within ${maxWaitSec}s`);
}

async function waitForNatGatewayDeleted(natGatewayId, maxWaitSec = 300, context) {
  const startTime = Date.now();
  while (Date.now() - startTime < maxWaitSec * 1000) {
    if (context?.getRemainingTimeInMillis?.() < 45_000) {
      throw new Error('NAT Gateway deletion wait stopped before the Lambda timeout.');
    }
    try {
      const desc = await ec2.send(new DescribeNatGatewaysCommand({
        NatGatewayIds: [natGatewayId],
      }));
      const state = desc.NatGateways?.[0]?.State;
      if (state === 'deleted') return;
    } catch (e) {
      if (e.name === 'NatGatewayNotFound' || e.name === 'InvalidNatGatewayID.NotFound') {
        return;
      }
      throw e;
    }
    await new Promise(r => setTimeout(r, 5000));
  }
  throw new Error(`NAT Gateway ${natGatewayId} was not deleted within ${maxWaitSec}s`);
}

async function selectAvailabilityZone() {
  const result = await ec2.send(new DescribeSubnetsCommand({
    Filters: [{ Name: 'vpc-id', Values: [VPC_ID] }],
  }));
  const selected = selectAvailabilityZoneName(result.Subnets, AWS_REGION);
  if ((result.Subnets || []).some(subnet => subnet.AvailabilityZone)) {
    return selected;
  }
  console.warn(JSON.stringify({
    level: 'WARN',
    event: 'DEDICATED_IP_AZ_FALLBACK',
    availabilityZone: selected,
  }));
  return selected;
}

async function createWorkerRole(roleName, tenantId, operationId) {
  const assumeRolePolicy = JSON.stringify({
    Version: '2012-10-17',
    Statement: [{
      Effect: 'Allow',
      Principal: { Service: 'lambda.amazonaws.com' },
      Action: 'sts:AssumeRole',
    }],
  });

  const result = await iam.send(new CreateRoleCommand({
    RoleName: roleName,
    AssumeRolePolicyDocument: assumeRolePolicy,
    Tags: [
      { Key: 'TenantId', Value: tenantId },
      { Key: 'ManagedBy', Value: 'vpnconfig-lambda' },
      { Key: 'OperationId', Value: operationId },
      { Key: 'Purpose', Value: 'dedicated-ip-ad-sync-worker' },
    ],
  }));

  // Attach managed policies
  await iam.send(new AttachRolePolicyCommand({
    RoleName: roleName,
    PolicyArn: 'arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole',
  }));

  // Inline policy for DynamoDB, Secrets Manager, S3, Cognito
  const inlinePolicy = JSON.stringify({
    Version: '2012-10-17',
    Statement: [
      {
        Effect: 'Allow',
        Action: ['dynamodb:GetItem', 'dynamodb:Query', 'dynamodb:UpdateItem', 'dynamodb:PutItem'],
        Resource: [
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${CONFIG_TABLE}`,
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${TENANT_TABLE}`,
          `arn:aws:dynamodb:${AWS_REGION}:${ACCOUNT_ID}:table/${TENANT_TABLE}/index/*`,
        ],
      },
      {
        Effect: 'Allow',
        Action: ['secretsmanager:GetSecretValue'],
        Resource: [`arn:aws:secretsmanager:${AWS_REGION}:${ACCOUNT_ID}:secret:apersona/*`],
      },
      {
        Effect: 'Allow',
        Action: ['s3:GetObject', 's3:PutObject', 's3:ListBucket'],
        Resource: [
          `arn:aws:s3:::${SYNC_STATE_BUCKET}`,
          `arn:aws:s3:::${SYNC_STATE_BUCKET}/*`,
        ],
      },
      {
        Effect: 'Allow',
        Action: [
          'cognito-idp:ListUsers',
          'cognito-idp:AdminCreateUser',
          'cognito-idp:AdminUpdateUserAttributes',
          'cognito-idp:AdminAddUserToGroup',
          'cognito-idp:AdminRemoveUserFromGroup',
          'cognito-idp:AdminListGroupsForUser',
          'cognito-idp:AdminDeleteUser',
          'cognito-idp:AdminGetUser',
          'cognito-idp:AdminDisableUser',
          'cognito-idp:AdminEnableUser',
          'cognito-idp:ListUsersInGroup',
          'cognito-idp:ListGroups',
          'cognito-idp:CreateGroup',
        ],
        Resource: [`arn:aws:cognito-idp:${AWS_REGION}:${ACCOUNT_ID}:userpool/*`],
      },
    ],
  });

  await iam.send(new PutRolePolicyCommand({
    RoleName: roleName,
    PolicyName: 'ad-sync-worker-permissions',
    PolicyDocument: inlinePolicy,
  }));

  return result.Role.Arn;
}

async function deleteWorkerRole(roleName) {
  try {
    await iam.send(new DetachRolePolicyCommand({
      RoleName: roleName,
      PolicyArn: 'arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole',
    }));
  } catch (error) {
    if (error.name !== 'NoSuchEntityException') throw error;
  }
  try {
    await iam.send(new DeleteRolePolicyCommand({
      RoleName: roleName,
      PolicyName: 'ad-sync-worker-permissions',
    }));
  } catch (error) {
    if (error.name !== 'NoSuchEntityException') throw error;
  }
  try {
    await iam.send(new DeleteRoleCommand({ RoleName: roleName }));
    console.log(JSON.stringify({ level: "INFO", event: "IAM_ROLE_DELETED", roleName }));
  } catch (error) {
    if (error.name !== 'NoSuchEntityException') throw error;
  }
}

/**
 * Rollback/cleanup all created resources (in reverse order).
 */
async function rollbackResources(tenantId, resources, { context } = {}) {
  const remaining = compactResourceJournal(resources);
  const deleted = [];
  const alreadyAbsent = [];
  const unresolved = [];
  const metadataKeys = [
    'eipAddress',
    'lambdaArn',
    'iamRoleArn',
    'workerCodeVersion',
    'workerCodeS3Key',
    'lastCodeUpdate',
  ];
  for (const key of metadataKeys) delete remaining[key];

  const runDelete = async (resourceType, resourceKey, action, notFoundNames = []) => {
    if (remaining[resourceKey] === null || remaining[resourceKey] === undefined) {
      delete remaining[resourceKey];
      return true;
    }
    if (context?.getRemainingTimeInMillis?.() < 45_000) {
      unresolved.push({
        resourceType,
        resourceId: remaining[resourceKey],
        errorCode: 'SOFT_DEADLINE',
      });
      return false;
    }
    try {
      await action(remaining[resourceKey]);
      deleted.push(resourceKey);
      delete remaining[resourceKey];
      return true;
    } catch (error) {
      if (notFoundNames.includes(error.name)) {
        alreadyAbsent.push(resourceKey);
        delete remaining[resourceKey];
        return true;
      }
      unresolved.push({
        resourceType,
        resourceId: remaining[resourceKey],
        errorCode: error.name || 'UnknownError',
      });
      return false;
    }
  };

  console.log(JSON.stringify({
    level: 'INFO',
    event: 'ROLLBACK_START',
    tenantId,
    resources: Object.keys(remaining),
  }));

  await runDelete('alarm', 'alarmName', async alarmName => {
    const cwClient = new CloudWatchClient({});
    await cwClient.send(new DeleteAlarmsCommand({ AlarmNames: [alarmName] }));
  });

  const lambdaDeleted = await runDelete(
    'lambda',
    'lambdaFunctionName',
    functionName => lambdaClient.send(new DeleteFunctionCommand({ FunctionName: functionName })),
    ['ResourceNotFoundException'],
  );

  if (lambdaDeleted) {
    await runDelete(
      'iam-role',
      'iamRoleName',
      roleName => deleteWorkerRole(roleName),
      ['NoSuchEntityException'],
    );
  }

  await runDelete(
    'nat-gateway',
    'natGatewayId',
    async natGatewayId => {
      try {
        await ec2.send(new DeleteNatGatewayCommand({ NatGatewayId: natGatewayId }));
      } catch (error) {
        if (!['NatGatewayNotFound', 'InvalidNatGatewayID.NotFound'].includes(error.name)) {
          throw error;
        }
      }
      await waitForNatGatewayDeleted(natGatewayId, 300, context);
    },
    ['NatGatewayNotFound', 'InvalidNatGatewayID.NotFound'],
  );

  const privateAssociationDeleted = await runDelete(
    'route-table-association',
    'privateRtAssociationId',
    associationId => ec2.send(new DisassociateRouteTableCommand({ AssociationId: associationId })),
    ['InvalidAssociationID.NotFound'],
  );
  if (privateAssociationDeleted) {
    await runDelete(
      'route-table',
      'privateRouteTableId',
      routeTableId => ec2.send(new DeleteRouteTableCommand({ RouteTableId: routeTableId })),
      ['InvalidRouteTableID.NotFound'],
    );
  }

  const publicAssociationDeleted = await runDelete(
    'route-table-association',
    'publicRtAssociationId',
    associationId => ec2.send(new DisassociateRouteTableCommand({ AssociationId: associationId })),
    ['InvalidAssociationID.NotFound'],
  );
  if (publicAssociationDeleted) {
    await runDelete(
      'route-table',
      'publicRouteTableId',
      routeTableId => ec2.send(new DeleteRouteTableCommand({ RouteTableId: routeTableId })),
      ['InvalidRouteTableID.NotFound'],
    );
  }

  if (remaining.securityGroupId) {
    // Sweep Lambda ENIs before deleting the SG. After DeleteFunction, Lambda
    // releases its Hyperplane ENI asynchronously: on a normal disable the ENI
    // stays 'in-use' for several minutes before turning 'available', and an
    // ENI in either state blocks SG and subnet deletion (DependencyViolation).
    // Wait for release within the soft deadline, deleting ENIs as they become
    // available. Non-fatal: on timeout the retry loop below and Retry Cleanup
    // still apply.
    try {
      for (let eniAttempt = 0; eniAttempt < 40; eniAttempt++) {
        const enis = await ec2.send(new DescribeNetworkInterfacesCommand({
          Filters: [{ Name: 'group-id', Values: [remaining.securityGroupId] }],
        }));
        const list = enis.NetworkInterfaces || [];
        if (!list.length) break;

        let deletedCount = 0;
        for (const eni of list.filter(e => e.Status === 'available')) {
          try {
            await ec2.send(new DeleteNetworkInterfaceCommand({
              NetworkInterfaceId: eni.NetworkInterfaceId,
            }));
            deletedCount++;
            console.log(JSON.stringify({
              level: 'INFO',
              event: 'ORPHAN_ENI_DELETED',
              tenantId,
              networkInterfaceId: eni.NetworkInterfaceId,
            }));
          } catch (eniError) {
            console.warn(JSON.stringify({
              level: 'WARN',
              event: 'ORPHAN_ENI_DELETE_FAILED',
              tenantId,
              networkInterfaceId: eni.NetworkInterfaceId,
              error: eniError.message,
            }));
          }
        }

        const inUseCount = list.filter(e => e.Status !== 'available').length;
        if (!inUseCount) {
          // No ENI is pending release. If deletions made progress, re-check;
          // if they all failed, nothing will change - stop instead of spinning.
          if (deletedCount > 0) continue;
          break;
        }
        if ((context?.getRemainingTimeInMillis?.() ?? Infinity) < 120_000) {
          console.warn(JSON.stringify({
            level: 'WARN',
            event: 'ENI_RELEASE_WAIT_DEADLINE',
            tenantId,
            inUseCount,
          }));
          break;
        }
        console.log(JSON.stringify({
          level: 'DEBUG',
          event: 'ENI_RELEASE_WAITING',
          tenantId,
          inUseCount,
          attempt: eniAttempt,
        }));
        await new Promise(resolve => setTimeout(resolve, 15_000));
      }
    } catch (sweepError) {
      console.warn(JSON.stringify({
        level: 'WARN',
        event: 'ORPHAN_ENI_SWEEP_FAILED',
        tenantId,
        error: sweepError.message,
      }));
    }

    let securityGroupError;
    for (let attempt = 0; attempt < 5; attempt++) {
      const deletedSecurityGroup = await runDelete(
        'security-group',
        'securityGroupId',
        groupId => ec2.send(new DeleteSecurityGroupCommand({ GroupId: groupId })),
        ['InvalidGroup.NotFound'],
      );
      if (deletedSecurityGroup) {
        securityGroupError = null;
        break;
      }
      securityGroupError = unresolved.pop();
      if (securityGroupError?.errorCode !== 'DependencyViolation' || attempt === 4) break;
      if (context?.getRemainingTimeInMillis?.() < 90_000) break;
      await new Promise(resolve => setTimeout(resolve, 15_000 * (attempt + 1)));
    }
    if (securityGroupError) unresolved.push(securityGroupError);
  }

  await runDelete(
    'subnet',
    'privateSubnetId',
    subnetId => ec2.send(new DeleteSubnetCommand({ SubnetId: subnetId })),
    ['InvalidSubnetID.NotFound'],
  );
  await runDelete(
    'subnet',
    'publicSubnetId',
    subnetId => ec2.send(new DeleteSubnetCommand({ SubnetId: subnetId })),
    ['InvalidSubnetID.NotFound'],
  );

  if (!remaining.natGatewayId) {
    await runDelete(
      'elastic-ip',
      'eipAllocationId',
      allocationId => ec2.send(new ReleaseAddressCommand({ AllocationId: allocationId })),
      ['InvalidAllocationID.NotFound'],
    );
  }

  if (canReleaseCidr(remaining) && remaining.cidrIndex !== undefined) {
    await runDelete(
      'cidr-allocation',
      'cidrIndex',
      cidrIndex => deallocateCidrIndex(cidrIndex, tenantId),
    );
  }

  console.log(JSON.stringify({
    level: unresolved.length ? 'WARN' : 'INFO',
    event: unresolved.length ? 'ROLLBACK_INCOMPLETE' : 'ROLLBACK_COMPLETE',
    tenantId,
    unresolvedCount: unresolved.length,
  }));
  return { deleted, alreadyAbsent, unresolved, remaining };
}

// ─── CIDR Allocation Tracker ─────────────────────────────────────────────────

async function allocateCidrIndex(tenantId, maxRetries = 5) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    // Read current allocation from DynamoDB
    const item = await dynamodb.send(new GetItemCommand({
      TableName: TENANT_TABLE,
      Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
    }));

    let nextIndex = CIDR_START_INDEX;
    let allocations = {};

    if (item.Item) {
      nextIndex = parseInt(item.Item.nextIndex?.N || String(CIDR_START_INDEX));
      allocations = JSON.parse(item.Item.allocations?.S || '{}');
    }

    const selection = selectCidrIndex(allocations, nextIndex, tenantId, {
      startIndex: CIDR_START_INDEX,
      maxIndex: CIDR_MAX_INDEX,
    });
    if (selection.existing) return selection.index;
    const allocatedIndex = selection.index;

    allocations[String(allocatedIndex)] = tenantId;

    const version = item.Item ? parseInt(item.Item.version?.N || '0') : 0;

    try {
      await dynamodb.send(new UpdateItemCommand({
        TableName: TENANT_TABLE,
        Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
        UpdateExpression: 'SET nextIndex = :next, allocations = :alloc, #t = :type, #v = :newVersion',
        // Optimistic lock: nextIndex + version must match what we read
        ConditionExpression: '(attribute_not_exists(nextIndex) OR nextIndex = :expected) AND (attribute_not_exists(#v) OR #v = :expectedVersion)',
        ExpressionAttributeNames: { '#t': 'type', '#v': 'version' },
        ExpressionAttributeValues: {
          ':next': { N: String(Math.max(nextIndex, allocatedIndex + 1)) },
          ':alloc': { S: JSON.stringify(allocations) },
          ':type': { S: 'cidr-allocation' },
          ':expected': { N: String(nextIndex) },
          ':newVersion': { N: String(version + 1) },
          ':expectedVersion': { N: String(version) },
        },
      }));

      return allocatedIndex;
    } catch (e) {
      if (e.name === 'ConditionalCheckFailedException') {
        // Another concurrent invocation allocated this index — retry
        console.log(JSON.stringify({ level: "WARN", event: "CIDR_ALLOC_CONFLICT", tenantId, attempt, nextIndex }));
        await new Promise(r => setTimeout(r, 100 * (attempt + 1))); // backoff
        continue;
      }
      throw e;
    }
  }

  throw new Error(`Failed to allocate CIDR index after ${maxRetries} retries (concurrent conflicts)`);
}

async function findCidrAllocation(tenantId) {
  const item = await dynamodb.send(new GetItemCommand({
    TableName: TENANT_TABLE,
    Key: {
      id: { S: 'DEDICATED_IP#cidr-index' },
      sk: { S: 'DEDICATED_IP#cidr-index' },
    },
  }));
  if (!item.Item) return undefined;
  const allocations = JSON.parse(item.Item.allocations?.S || '{}');
  const match = Object.entries(allocations).find(([, owner]) => owner === tenantId);
  return match ? Number(match[0]) : undefined;
}

async function deallocateCidrIndex(index, tenantId, maxRetries = 3) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const item = await dynamodb.send(new GetItemCommand({
        TableName: TENANT_TABLE,
        Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
      }));

      if (!item.Item) return;

      const allocations = JSON.parse(item.Item.allocations?.S || '{}');
      const version = parseInt(item.Item.version?.N || '0');
      try {
        if (!assertCidrOwnership(allocations, index, tenantId)) return;
      } catch (error) {
        console.error(JSON.stringify({
          level: 'ERROR',
          event: 'CIDR_DEALLOC_OWNER_MISMATCH',
          index,
          tenantId,
          currentOwner: allocations[String(index)],
        }));
        throw error;
      }
      delete allocations[String(index)];

      try {
        await dynamodb.send(new UpdateItemCommand({
          TableName: TENANT_TABLE,
          Key: { id: { S: 'DEDICATED_IP#cidr-index' }, sk: { S: 'DEDICATED_IP#cidr-index' } },
          UpdateExpression: 'SET allocations = :alloc, #v = :newVersion',
          // Optimistic lock on version to prevent lost updates with concurrent allocateCidrIndex
          ConditionExpression: '#v = :expectedVersion OR attribute_not_exists(#v)',
          ExpressionAttributeNames: { '#v': 'version' },
          ExpressionAttributeValues: {
            ':alloc': { S: JSON.stringify(allocations) },
            ':newVersion': { N: String(version + 1) },
            ':expectedVersion': { N: String(version) },
          },
        }));
        return; // success
      } catch (e) {
        if (e.name === 'ConditionalCheckFailedException') {
          console.log(JSON.stringify({ level: "WARN", event: "CIDR_DEALLOC_CONFLICT", index, tenantId, attempt }));
          await new Promise(r => setTimeout(r, 100 * (attempt + 1)));
          continue;
        }
        throw e;
      }
    } catch (e) {
      console.warn(JSON.stringify({ level: "WARN", event: "CIDR_DEALLOC_FAILED", index, tenantId, error: e.message }));
      throw e;
    }
  }
  throw new Error(`Failed to deallocate CIDR index ${index} after ${maxRetries} retries`);
}
