import {
  GetItemCommand,
  PutItemCommand,
  UpdateItemCommand,
} from '@aws-sdk/client-dynamodb';

export const DEDICATED_IP_CONFIG_TYPE = 'dedicatedIpState';
export const STALE_AFTER_MS = 20 * 60 * 1000;
export const TRANSITIONAL_MODES = new Set([
  'provisioning',
  'rolling_back',
  'deprovisioning',
]);

export class StateConflictError extends Error {
  constructor(message, current = null) {
    super(message);
    this.name = 'StateConflictError';
    this.current = current;
  }
}

export async function runEnqueueCompensation({
  compensate,
  tenantId,
  action,
}) {
  try {
    await compensate();
  } catch (error) {
    console.error(JSON.stringify({
      level: 'ERROR',
      event: 'DEDICATED_IP_ENQUEUE_COMPENSATION_FAILED',
      tenantId,
      action,
      error: error.message,
    }));
  }
}

export function logEnqueueFailure({ tenantId, action, error }) {
  console.error(JSON.stringify({
    level: 'ERROR',
    event: 'DEDICATED_IP_ENQUEUE_FAILED',
    tenantId,
    action,
    error: error.message,
  }));
}

function toAttribute(value) {
  if (value === null || value === undefined) return { NULL: true };
  if (typeof value === 'string') return { S: value };
  if (typeof value === 'number') return { N: String(value) };
  if (typeof value === 'boolean') return { BOOL: value };
  if (Array.isArray(value)) return { L: value.map(toAttribute) };
  return {
    M: Object.fromEntries(
      Object.entries(value)
        .filter(([, child]) => child !== undefined)
        .map(([key, child]) => [key, toAttribute(child)]),
    ),
  };
}

function fromAttribute(attribute) {
  if (!attribute || attribute.NULL) return null;
  if ('S' in attribute) return attribute.S;
  if ('N' in attribute) return Number(attribute.N);
  if ('BOOL' in attribute) return attribute.BOOL;
  if ('L' in attribute) return attribute.L.map(fromAttribute);
  if ('M' in attribute) {
    return Object.fromEntries(
      Object.entries(attribute.M).map(([key, child]) => [key, fromAttribute(child)]),
    );
  }
  return undefined;
}

export function serializeStateItem(tenantId, state) {
  return {
    id: { S: tenantId },
    configtype: { S: DEDICATED_IP_CONFIG_TYPE },
    ...Object.fromEntries(
      Object.entries(state)
        .filter(([, value]) => value !== undefined)
        .map(([key, value]) => [key, toAttribute(value)]),
    ),
  };
}

export function deserializeStateItem(item) {
  if (!item) return null;
  const state = {};
  for (const [key, value] of Object.entries(item)) {
    if (key !== 'id' && key !== 'configtype') state[key] = fromAttribute(value);
  }
  return state;
}

export function isStale(state, now = new Date()) {
  if (!state?.startedAt || !TRANSITIONAL_MODES.has(state.mode)) return false;
  return now.getTime() - new Date(state.startedAt).getTime() > STALE_AFTER_MS;
}

export function toPublicDedicatedIpState(state, now = new Date()) {
  const resolved = state || { mode: 'shared', resources: {} };
  return {
    mode: resolved.mode || 'shared',
    dedicatedEipAddress: resolved.dedicatedEipAddress || null,
    error: typeof resolved.error === 'string'
      ? resolved.error
      : resolved.error?.message || null,
    startedAt: resolved.startedAt || null,
    updatedAt: resolved.updatedAt || null,
    canRetryCleanup: resolved.mode === 'cleanup_failed',
    canRecover: isStale(resolved, now),
  };
}

function errorRecord(code, message, at) {
  return { code, message, at };
}

function hasResources(state) {
  return Object.keys(state?.resources || {}).length > 0;
}

export function createDedicatedIpStateStore({
  client,
  tableName,
  now = () => new Date(),
}) {
  const key = (tenantId) => ({
    id: { S: tenantId },
    configtype: { S: DEDICATED_IP_CONFIG_TYPE },
  });

  async function load(tenantId) {
    const result = await client.send(new GetItemCommand({
      TableName: tableName,
      Key: key(tenantId),
      ConsistentRead: true,
    }));
    return deserializeStateItem(result.Item);
  }

  async function put(tenantId, next, expected) {
    const names = {};
    const values = {};
    const conditions = [];

    if (!expected) {
      names['#id'] = 'id';
      conditions.push('attribute_not_exists(#id)');
    } else {
      names['#mode'] = 'mode';
      values[':expectedMode'] = { S: expected.mode };
      conditions.push('#mode = :expectedMode');

      if (expected.operationId !== undefined) {
        names['#operationId'] = 'operationId';
        values[':expectedOperationId'] = { S: expected.operationId };
        conditions.push('#operationId = :expectedOperationId');
      }
      if (expected.phase !== undefined) {
        names['#phase'] = 'phase';
        values[':expectedPhase'] = { S: expected.phase };
        conditions.push('#phase = :expectedPhase');
      }
      if (expected.startedAt !== undefined) {
        names['#startedAt'] = 'startedAt';
        values[':expectedStartedAt'] = { S: expected.startedAt };
        conditions.push('#startedAt = :expectedStartedAt');
      }
      if (expected.resourcesEmpty) {
        names['#resources'] = 'resources';
        values[':zero'] = { N: '0' };
        conditions.push('(attribute_not_exists(#resources) OR size(#resources) = :zero)');
      }
    }

    try {
      await client.send(new PutItemCommand({
        TableName: tableName,
        Item: serializeStateItem(tenantId, next),
        ConditionExpression: conditions.join(' AND '),
        ExpressionAttributeNames: names,
        ...(Object.keys(values).length ? { ExpressionAttributeValues: values } : {}),
      }));
      return next;
    } catch (error) {
      if (error.name !== 'ConditionalCheckFailedException') throw error;
      throw new StateConflictError('Dedicated IP state changed concurrently', await load(tenantId));
    }
  }

  function queuedState(mode, operationId, current = {}) {
    const timestamp = now().toISOString();
    return {
      mode,
      phase: 'queued',
      operationId,
      startedAt: timestamp,
      updatedAt: timestamp,
      resources: { ...(current.resources || {}) },
      ...(current.dedicatedEipAddress
        ? { dedicatedEipAddress: current.dedicatedEipAddress }
        : {}),
      ...(current.dedicatedLambdaArn
        ? { dedicatedLambdaArn: current.dedicatedLambdaArn }
        : {}),
      ...(current.resourceOperationId
        ? { resourceOperationId: current.resourceOperationId }
        : {}),
    };
  }

  async function beginEnable(tenantId, operationId) {
    const current = await load(tenantId);
    if (current && (current.mode !== 'shared' || hasResources(current))) {
      throw new StateConflictError('Dedicated IP is not in shared state', current);
    }
    return put(tenantId, queuedState('provisioning', operationId), current);
  }

  async function beginCleanup(tenantId, operationId) {
    const current = await load(tenantId);
    if (current?.mode === 'dedicated') {
      const state = await put(
        tenantId,
        queuedState('deprovisioning', operationId, current),
        { mode: 'dedicated', operationId: current.operationId },
      );
      return { state, previous: current };
    }
    if (current?.mode === 'cleanup_failed') {
      const state = await put(
        tenantId,
        queuedState('deprovisioning', operationId, current),
        { mode: 'cleanup_failed', operationId: current.operationId },
      );
      return { state, previous: current };
    }
    throw new StateConflictError('Dedicated IP cleanup cannot start', current);
  }

  async function claim(tenantId, mode, operationId) {
    const current = await load(tenantId);
    if (current?.mode !== mode || current.phase !== 'queued' || current.operationId !== operationId) {
      throw new StateConflictError('Dedicated IP event no longer owns the operation', current);
    }
    const timestamp = now().toISOString();
    return put(
      tenantId,
      { ...current, phase: 'running', startedAt: timestamp, updatedAt: timestamp },
      { mode, phase: 'queued', operationId },
    );
  }

  async function checkpointResource(tenantId, mode, operationId, resourceName, value) {
    const timestamp = now().toISOString();
    try {
      await client.send(new UpdateItemCommand({
        TableName: tableName,
        Key: key(tenantId),
        UpdateExpression: 'SET #resources.#resourceName = :resourceValue, #updatedAt = :updatedAt',
        ConditionExpression: '#mode = :mode AND #phase = :running AND #operationId = :operationId',
        ExpressionAttributeNames: {
          '#resources': 'resources',
          '#resourceName': resourceName,
          '#updatedAt': 'updatedAt',
          '#mode': 'mode',
          '#phase': 'phase',
          '#operationId': 'operationId',
        },
        ExpressionAttributeValues: {
          ':resourceValue': toAttribute(value),
          ':updatedAt': { S: timestamp },
          ':mode': { S: mode },
          ':running': { S: 'running' },
          ':operationId': { S: operationId },
        },
      }));
    } catch (error) {
      if (error.name !== 'ConditionalCheckFailedException') throw error;
      throw new StateConflictError('Dedicated IP checkpoint lost operation ownership', await load(tenantId));
    }
  }

  async function completeProvisioning(tenantId, operationId, {
    dedicatedEipAddress,
    dedicatedLambdaArn,
    resources,
  }) {
    const current = await load(tenantId);
    const timestamp = now().toISOString();
    return put(tenantId, {
      mode: 'dedicated',
      operationId,
      updatedAt: timestamp,
      dedicatedEipAddress,
      dedicatedLambdaArn,
      resourceOperationId: operationId,
      resources: { ...(resources || current?.resources || {}) },
    }, { mode: 'provisioning', phase: 'running', operationId });
  }

  async function queueRollback(tenantId, operationId, message) {
    const current = await load(tenantId);
    const timestamp = now().toISOString();
    return put(tenantId, {
      ...queuedState('rolling_back', operationId, current),
      resourceOperationId: operationId,
      error: errorRecord(
        'PROVISIONING_FAILED',
        message || 'Provisioning failed; created resources are being removed.',
        timestamp,
      ),
    }, { mode: 'provisioning', phase: 'running', operationId });
  }

  async function recordCleanupProgress(tenantId, mode, operationId, resources) {
    const timestamp = now().toISOString();
    try {
      await client.send(new UpdateItemCommand({
        TableName: tableName,
        Key: key(tenantId),
        UpdateExpression: 'SET #resources = :resources, #updatedAt = :updatedAt',
        ConditionExpression: '#mode = :mode AND #phase = :running AND #operationId = :operationId',
        ExpressionAttributeNames: {
          '#resources': 'resources',
          '#updatedAt': 'updatedAt',
          '#mode': 'mode',
          '#phase': 'phase',
          '#operationId': 'operationId',
        },
        ExpressionAttributeValues: {
          ':resources': toAttribute(resources || {}),
          ':updatedAt': { S: timestamp },
          ':mode': { S: mode },
          ':running': { S: 'running' },
          ':operationId': { S: operationId },
        },
      }));
    } catch (error) {
      if (error.name !== 'ConditionalCheckFailedException') throw error;
      throw new StateConflictError(
        'Dedicated IP cleanup progress lost operation ownership',
        await load(tenantId),
      );
    }
  }

  async function completeCleanup(tenantId, mode, operationId, previousError = null) {
    const current = await load(tenantId);
    if (hasResources(current)) {
      throw new Error('Cannot complete cleanup while resources remain');
    }
    const timestamp = now().toISOString();
    return put(tenantId, {
      mode: 'shared',
      operationId,
      updatedAt: timestamp,
      resources: {},
      ...(previousError ? { error: previousError } : {}),
    }, {
      mode,
      phase: 'running',
      operationId,
      resourcesEmpty: true,
    });
  }

  async function failCleanup(tenantId, mode, operationId, resources, message) {
    const current = await load(tenantId);
    const timestamp = now().toISOString();
    return put(tenantId, {
      mode: 'cleanup_failed',
      operationId,
      updatedAt: timestamp,
      resources: { ...(resources || {}) },
      ...(resources?.eipAllocationId && current?.dedicatedEipAddress
        ? { dedicatedEipAddress: current.dedicatedEipAddress }
        : {}),
      ...(current?.resourceOperationId
        ? { resourceOperationId: current.resourceOperationId }
        : {}),
      error: errorRecord(
        'CLEANUP_FAILED',
        message || 'Cleanup did not complete. Retry cleanup.',
        timestamp,
      ),
    }, { mode, phase: 'running', operationId });
  }

  async function restoreEnqueueFailure(tenantId, queuedMode, operationId, previous, message) {
    const timestamp = now().toISOString();
    const restored = {
      ...previous,
      updatedAt: timestamp,
      error: errorRecord('ENQUEUE_FAILED', message, timestamp),
    };
    delete restored.phase;
    delete restored.startedAt;
    return put(tenantId, restored, {
      mode: queuedMode,
      phase: 'queued',
      operationId,
    });
  }

  async function failCleanupEnqueue(tenantId, mode, operationId) {
    const current = await load(tenantId);
    const timestamp = now().toISOString();
    return put(tenantId, {
      mode: 'cleanup_failed',
      operationId,
      updatedAt: timestamp,
      resources: { ...(current?.resources || {}) },
      ...(current?.dedicatedEipAddress
        ? { dedicatedEipAddress: current.dedicatedEipAddress }
        : {}),
      ...(current?.resourceOperationId
        ? { resourceOperationId: current.resourceOperationId }
        : {}),
      error: errorRecord(
        'CLEANUP_ENQUEUE_FAILED',
        'Cleanup could not be started. Retry cleanup.',
        timestamp,
      ),
    }, { mode, phase: 'queued', operationId });
  }

  async function recoverStale(tenantId, operationId) {
    const current = await load(tenantId);
    if (!isStale(current, now())) {
      throw new StateConflictError('Dedicated IP operation is not recoverable', current);
    }
    const targetMode = current.mode === 'deprovisioning'
      ? 'deprovisioning'
      : 'rolling_back';
    const next = queuedState(targetMode, operationId, current);
    next.resourceOperationId = current.resourceOperationId || current.operationId;
    if (current.error) next.error = current.error;
    if (current.mode === 'provisioning' && !next.error) {
      const timestamp = now().toISOString();
      next.error = errorRecord(
        'PROVISIONING_TIMED_OUT',
        'Provisioning did not complete; created resources are being removed.',
        timestamp,
      );
    }
    return put(tenantId, next, {
      mode: current.mode,
      operationId: current.operationId,
      phase: current.phase,
      startedAt: current.startedAt,
    });
  }

  return {
    load,
    beginEnable,
    beginCleanup,
    claim,
    checkpointResource,
    completeProvisioning,
    queueRollback,
    recordCleanupProgress,
    completeCleanup,
    failCleanup,
    restoreEnqueueFailure,
    failCleanupEnqueue,
    recoverStale,
  };
}
