import {
  GetSecretValueCommand,
  SecretsManagerClient,
} from '@aws-sdk/client-secrets-manager';

const REQUIRED_FIELDS = [
  'tenantId',
  'tenantName',
  'tenantAdminEmail',
  'requestedBy',
  'awsAccountId',
  'asmSecretKey',
  'appSrvIP',
];

export function buildAsmAppSrvIpForm(fields) {
  const missingFields = REQUIRED_FIELDS.filter(field => !fields[field]);
  if (missingFields.length) {
    throw new Error(`Missing ASM tenantAdmin fields: ${missingFields.join(', ')}`);
  }

  return new URLSearchParams({
    tenantId: String(fields.tenantId),
    tenantName: fields.tenantName,
    tenantAdminEmail: fields.tenantAdminEmail,
    action: 'add',
    requestedBy: fields.requestedBy,
    awsAccountId: fields.awsAccountId,
    asmSecretKey: fields.asmSecretKey,
    appSrvIP: fields.appSrvIP,
  });
}

export async function updateAsmAppSrvIP(tenantId, newIpAddress, {
  asmPortalUrl = process.env.ASM_PORTAL_URL || '',
  awsAccountId = process.env.ACCOUNT_ID || '',
  secretsManager = new SecretsManagerClient({}),
  fetchImpl = fetch,
  timeoutSignal = () => AbortSignal.timeout(10_000),
  logger = console,
} = {}) {
  if (!asmPortalUrl || !newIpAddress) {
    logger.log(JSON.stringify({
      level: 'DEBUG',
      event: 'ASM_APPSRVIP_SKIP',
      tenantId,
      reason: 'ASM not configured or no IP',
    }));
    return false;
  }

  try {
    let tenantCredentials;
    try {
      const secret = await secretsManager.send(new GetSecretValueCommand({
        SecretId: `apersona/asm/tenant/${tenantId}`,
      }));
      tenantCredentials = JSON.parse(secret.SecretString);
    } catch (error) {
      logger.warn(JSON.stringify({
        level: 'WARN',
        event: 'ASM_TENANT_SECRET_NOT_FOUND',
        tenantId,
      }));
      return false;
    }

    const {
      asmClientId,
      asmClientName: tenantName,
      awsAdminEmail: tenantAdminEmail,
      orgId,
    } = tenantCredentials;
    const missingContext = Object.entries({
      asmClientId,
      tenantName,
      tenantAdminEmail,
      orgId,
    })
      .filter(([, value]) => !value)
      .map(([field]) => field);
    if (missingContext.length) {
      logger.warn(JSON.stringify({
        level: 'WARN',
        event: 'ASM_TENANT_CONTEXT_INCOMPLETE',
        tenantId,
        missingFields: missingContext,
      }));
      return false;
    }

    let asmSecretKey;
    try {
      const secret = await secretsManager.send(new GetSecretValueCommand({
        SecretId: `apersona/asm/org/${orgId}`,
      }));
      asmSecretKey = JSON.parse(secret.SecretString).asmSecretKey;
    } catch (error) {
      logger.warn(JSON.stringify({
        level: 'WARN',
        event: 'ASM_ORG_SECRET_NOT_FOUND',
        tenantId,
        orgId,
      }));
      return false;
    }
    if (!asmSecretKey) {
      logger.warn(JSON.stringify({
        level: 'WARN',
        event: 'ASM_ORG_CONTEXT_INCOMPLETE',
        tenantId,
        orgId,
        missingFields: ['asmSecretKey'],
      }));
      return false;
    }

    const formData = buildAsmAppSrvIpForm({
      tenantId: asmClientId,
      tenantName,
      tenantAdminEmail,
      requestedBy: 'vpnconfig-dedicated-ip',
      awsAccountId,
      asmSecretKey,
      appSrvIP: newIpAddress,
    });
    const response = await fetchImpl(`${asmPortalUrl}/tenantAdmin.ap`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formData.toString(),
      signal: timeoutSignal(),
    });

    if (!response.ok) {
      logger.warn(JSON.stringify({
        level: 'WARN',
        event: 'ASM_APPSRVIP_FAILED',
        tenantId,
        status: response.status,
      }));
      return false;
    }

    logger.log(JSON.stringify({
      level: 'INFO',
      event: 'ASM_APPSRVIP_UPDATED',
      tenantId,
      appSrvIP: newIpAddress,
    }));
    return true;
  } catch (error) {
    logger.warn(JSON.stringify({
      level: 'WARN',
      event: 'ASM_APPSRVIP_ERROR',
      tenantId,
      error: error.message,
    }));
    return false;
  }
}
